struct Config { string listen,root,origin,auth; uint64_t maxconn=0,header=0,headms=0,idlems=0,writems=0,maxreq=0,pipe=0,authms=0; sockaddr_in la{},oa{},aa{}; } cfg;
bool number(const string&s,uint64_t&v){if(s.empty())return false; v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return v>0;}
bool address(const string&s,sockaddr_in&a){auto p=s.rfind(':');if(p==string::npos)return false;string h=s.substr(0,p),port=s.substr(p+1);uint64_t n;if(!number(port,n)||n>65535)return false;memset(&a,0,sizeof a);a.sin_family=AF_INET;a.sin_port=htons(n);return inet_pton(AF_INET,h.c_str(),&a.sin_addr)==1;}
bool config(const char*path){ifstream f(path);if(!f)return false;unordered_map<string,string> m;string l;while(getline(f,l)){if(!l.empty()&&l.back()=='\r')l.pop_back();if(l.empty()||l[0]=='#')continue;auto p=l.find('=');if(p==string::npos||p==0||m.count(l.substr(0,p)))return false;m[l.substr(0,p)]=l.substr(p+1);}const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","auth_address","auth_timeout_ms"};if(m.size()!=keys.size())return false;for(auto&k:keys)if(!m.count(k))return false;cfg.listen=m["listen"];cfg.root=m["root"];cfg.origin=m["origin_address"];cfg.auth=m["auth_address"];if(cfg.root.empty()||cfg.root[0]!='/')return false;struct stat st;if(stat(cfg.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;return address(cfg.listen,cfg.la)&&address(cfg.origin,cfg.oa)&&address(cfg.auth,cfg.aa)&&number(m["max_connections"],cfg.maxconn)&&number(m["header_bytes"],cfg.header)&&number(m["header_timeout_ms"],cfg.headms)&&number(m["idle_timeout_ms"],cfg.idlems)&&number(m["write_timeout_ms"],cfg.writems)&&number(m["max_requests"],cfg.maxreq)&&number(m["pipeline_depth"],cfg.pipe)&&number(m["auth_timeout_ms"],cfg.authms)&&cfg.header<=16*1024*1024&&cfg.maxconn<=10000000&&cfg.headms<=INT_MAX&&cfg.idlems<=INT_MAX&&cfg.writems<=INT_MAX&&cfg.authms<=INT_MAX;}
int ep,rootfd,listener; uint64_t nextid=1;
string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
string trim(string_view x){while(!x.empty()&&(x.front()==' '||x.front()=='\t'))x.remove_prefix(1);while(!x.empty()&&(x.back()==' '||x.back()=='\t'))x.remove_suffix(1);return string(x);}
bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='a'&&c<='z')||(c>='A'&&c<='Z')||strchr("!#$%&'*+-.^_`|~",c);}
bool decimal(const string&s,uint64_t&n){if(s.empty())return false;n=0;for(unsigned char c:s){if(c<'0'||c>'9'||n>(UINT64_MAX-(c-'0'))/10)return false;n=n*10+c-'0';}return true;}
bool hastoken(const string&s,const string&t){size_t p=0;while(p<=s.size()){auto q=s.find(',',p);if(q==string::npos)q=s.size();if(lower(trim(string_view(s).substr(p,q-p)))==t)return true;if(q==s.size())break;p=q+1;}return false;}
bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<0x80)continue;int n;uint32_t u;if(c>=0xc2&&c<=0xdf){n=1;u=c&31;}else if(c>=0xe0&&c<=0xef){n=2;u=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;u=c&7;}else return false;if(i+n>s.size())return false;for(int j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;u=(u<<6)|(d&63);}if((n==2&&u<0x800)||(n==3&&u<0x10000)||u>0x10ffff||(u>=0xd800&&u<=0xdfff))return false;}return true;}
int hexv(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
int decodepath(const string&t,string&path){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return 400;size_t end=t.find('?');if(end==string::npos)end=t.size();path.clear();for(size_t i=0;i<end;i++){unsigned char c=t[i];if(c=='%'){if(i+2>=end)return 400;int a=hexv(t[i+1]),b=hexv(t[i+2]);if(a<0||b<0)return 400;c=(a<<4)|b;i+=2;}if(c==0||c=='\\')return 400;path.push_back(c);}if(!utf8(path))return 400;size_t p=0;while(p<path.size()){size_t q=path.find('/',p);if(q==string::npos)q=path.size();if(path.substr(p,q-p)=="..")return 403;p=q+1;}return 0;}
struct Request{string method,target,path,host,auth,version;bool close=false,auth_present=false;};
struct Conn{uint64_t id;int fd,up=-1,file=-1;enum State{READ,AUTH,ORIGIN,RESPONSE} state=READ;string in,out,upsend,uphead;size_t opos=0,uspos=0;bool connecting=false,upheaders=false,source_done=true,closing=false,head=false;uint64_t requests=0,remaining=0,fileleft=0;Time first{},last=Clock::now(),progress=Clock::now(),upstart=Clock::now();Request req;};
unordered_map<uint64_t,unique_ptr<Conn>> conns;
void ctl(int op,int fd,uint64_t data,uint32_t events){epoll_event ev{};ev.events=events;ev.data.u64=data;epoll_ctl(ep,op,fd,&ev);}
void closeup(Conn&c){if(c.up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c.up,nullptr);close(c.up);c.up=-1;}}
void eraseconn(uint64_t id){auto it=conns.find(id);if(it==conns.end())return;Conn&c=*it->second;closeup(c);if(c.file>=0)close(c.file);epoll_ctl(ep,EPOLL_CTL_DEL,c.fd,nullptr);close(c.fd);conns.erase(it);}
void update(Conn&c){uint32_t ev=EPOLLRDHUP;if(c.state==Conn::READ)ev|=EPOLLIN;if(c.opos<c.out.size()||c.fileleft)ev|=EPOLLOUT;ctl(EPOLL_CTL_MOD,c.fd,c.id<<1,ev);if(c.up>=0){uint32_t ue=EPOLLRDHUP;if(c.connecting||c.uspos<c.upsend.size())ue|=EPOLLOUT;else if(c.state==Conn::AUTH||!c.upheaders||c.out.size()-c.opos<131072)ue|=EPOLLIN;ctl(EPOLL_CTL_MOD,c.up,(c.id<<1)|1,ue);}}
string reason(int code){switch(code){case 200:return "OK";case 400:return "Bad Request";case 401:return "Unauthorized";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 408:return "Request Timeout";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";case 503:return "Service Unavailable";default:return "Response";}}
void response(Conn&c,int code,uint64_t len,bool force=false,const string&extra=""){c.closing=c.closing||force;c.out="HTTP/1.1 "+to_string(code)+" "+reason(code)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(c.closing?"close":"keep-alive")+"\r\n"+extra+"\r\n";c.opos=0;c.progress=Clock::now();}
void fail(Conn&c,int code,bool force){closeup(c);if(c.file>=0){close(c.file);c.file=-1;}c.fileleft=0;c.state=Conn::RESPONSE;c.source_done=true;response(c,code,0,force);update(c);}
bool validlinebytes(const string&s){for(size_t i=0;i<s.size();i++){unsigned char c=s[i];if(c==0||c=='\n'&&(i==0||s[i-1]!='\r')||c=='\r'&&i+1<s.size()&&s[i+1]!='\n')return false;}return true;}
int parse_request(const string&h,Request&r){if(!validlinebytes(h))return 400;size_t e=h.find("\r\n");if(e==string::npos)return 400;string line=h.substr(0,e);auto a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);if(a==string::npos||b==string::npos||a==0||b==a+1||line.find(' ',b+1)!=string::npos)return 400;r.method=line.substr(0,a);r.target=line.substr(a+1,b-a-1);r.version=line.substr(b+1);for(unsigned char c:r.method)if(!tokenchar(c))return 400;for(unsigned char c:r.target)if(c<=32||c==127)return 400;if(r.version!="HTTP/1.1"&&r.version!="HTTP/1.0")return 400;int hosts=0,auths=0,cls=0;bool te=false;string conn,cl;size_t p=e+2;while(p<h.size()){size_t q=h.find("\r\n",p);if(q==string::npos)return 400;if(q==p)break;string_view ln(h.data()+p,q-p);size_t colon=ln.find(':');if(colon==string_view::npos||colon==0)return 400;for(size_t i=0;i<colon;i++)if(!tokenchar((unsigned char)ln[i]))return 400;for(size_t i=colon+1;i<ln.size();i++){unsigned char ch=ln[i];if((ch<32&&ch!='\t')||ch==127)return 400;}string k=lower(string(ln.substr(0,colon))),v=trim(ln.substr(colon+1));if(k=="host"){hosts++;r.host=v;}else if(k=="authorization"){auths++;r.auth=v;r.auth_present=true;}else if(k=="content-length"){cls++;cl=v;}else if(k=="transfer-encoding")te=true;else if(k=="connection"){if(!conn.empty())conn+=',';conn+=v;}p=q+2;}if(cls>1||te)return 400;if(cls){uint64_t n;if(!decimal(cl,n)||n!=0)return 400;}if(auths>1)return 400;r.close=r.version=="HTTP/1.0"||hastoken(conn,"close");int result=decodepath(r.target,r.path);if(result)return result;if(r.target.rfind("/gateway/",0)==0&&(hosts!=1||r.host.empty()))return 400;if(r.method!="GET"&&r.method!="HEAD")return 405;return 0;}
int openfile(const string&path,int&fd,uint64_t&size){vector<string> parts;size_t p=0;while(p<path.size()){size_t q=path.find('/',p);if(q==string::npos)q=path.size();string x=path.substr(p,q-p);if(!x.empty()&&x!=".")parts.push_back(x);p=q+1;}if(parts.empty())return 403;int dir=dup(rootfd);if(dir<0)return 403;for(size_t i=0;i<parts.size();i++){bool last=i+1==parts.size();int flags=O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK;if(!last)flags|=O_DIRECTORY;int n=openat(dir,parts[i].c_str(),flags);if(n<0){int err=errno;struct stat st{};bool sym=fstatat(dir,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(dir);if(sym||err==ELOOP||err==EACCES||err==EPERM)return 403;if(err==ENOENT||err==ENOTDIR)return 404;return 403;}close(dir);dir=n;}struct stat st{};if(fstat(dir,&st)||!S_ISREG(st.st_mode)||(!path.empty()&&path.back()=='/')){close(dir);return 403;}if(st.st_size<0){close(dir);return 403;}fd=dir;size=st.st_size;return 0;}
bool startup(Conn&c,bool auth){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0)return false;auto &addr=auth?cfg.aa:cfg.oa;int rc=connect(fd,(sockaddr*)&addr,sizeof(addr));if(rc<0&&errno!=EINPROGRESS){close(fd);return false;}c.up=fd;c.connecting=rc<0;c.upstart=c.progress=Clock::now();c.upheaders=false;c.uphead.clear();c.uspos=0;c.source_done=false;if(auth){c.state=Conn::AUTH;c.upsend="GET /authorize HTTP/1.1\r\nHost: "+c.req.host+"\r\nX-Original-URI: "+c.req.target+"\r\n";if(c.req.auth_present)c.upsend+="Authorization: "+c.req.auth+"\r\n";c.upsend+="Content-Length: 0\r\nConnection: close\r\n\r\n";}else{c.state=Conn::ORIGIN;string target=c.req.target.substr(8);if(target.empty()||target[0]!='/' )target="/"+target;c.upsend=c.req.method+" "+target+" HTTP/1.1\r\nHost: "+c.req.host+"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";}ctl(EPOLL_CTL_ADD,fd,(c.id<<1)|1,EPOLLOUT|EPOLLRDHUP);update(c);return true;}
void process_request(Conn&c){auto end=c.in.find("\r\n\r\n");if(end==string::npos){if(!validlinebytes(c.in)){fail(c,400,true);return;}if(c.in.size()>=cfg.header){fail(c,431,true);return;}return;}if(end+4>cfg.header){fail(c,431,true);return;}string h=c.in.substr(0,end+4);c.in.erase(0,end+4);c.req=Request{};int err=parse_request(h,c.req);c.closing=c.req.close||c.requests+1>=cfg.maxreq;c.head=c.req.method=="HEAD";if(err){fail(c,err,err==400||err==431);return;}if(c.req.target.rfind("/gateway/",0)==0){if(!startup(c,true))fail(c,503,false);return;}int fd=-1;uint64_t len=0;err=openfile(c.req.path,fd,len);if(err){fail(c,err,false);return;}c.state=Conn::RESPONSE;c.source_done=true;response(c,200,len,false,"Content-Type: application/octet-stream\r\n");if(c.head||len==0){close(fd);c.file=-1;c.fileleft=0;}else{c.file=fd;c.fileleft=len;}update(c);}
void readclient(Conn&c){while(c.state==Conn::READ){if(!c.in.empty()){process_request(c);if(c.state!=Conn::READ)return;}size_t cap=(size_t)cfg.header+1;if(c.in.size()>=cap){fail(c,431,true);return;}char b[16384];size_t want=min(sizeof b,cap-c.in.size());ssize_t n=recv(c.fd,b,want,0);if(n>0){auto now=Clock::now();if(c.in.empty())c.first=now;c.last=now;c.in.append(b,n);process_request(c);if(c.state!=Conn::READ)return;continue;}if(n==0){eraseconn(c.id);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;eraseconn(c.id);return;}}
void done(Conn&c){if(c.closing){eraseconn(c.id);return;}c.requests++;c.state=Conn::READ;c.out.clear();c.opos=0;c.last=Clock::now();if(!c.in.empty()){process_request(c);}if(c.state==Conn::READ)update(c);}
void writeclient(Conn&c){while(c.opos<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.opos,c.out.size()-c.opos,MSG_NOSIGNAL);if(n>0){c.opos+=n;c.progress=Clock::now();continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){update(c);return;}eraseconn(c.id);return;}if(c.opos==c.out.size()){c.out.clear();c.opos=0;}while(c.fileleft){ssize_t n=sendfile(c.fd,c.file,nullptr,min<uint64_t>(c.fileleft,1<<20));if(n>0){c.fileleft-=n;c.progress=Clock::now();continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){update(c);return;}eraseconn(c.id);return;}if(c.file>=0){close(c.file);c.file=-1;}if(c.source_done&&(c.state==Conn::RESPONSE||c.state==Conn::ORIGIN)){done(c);return;}update(c);}
bool upstream_header(const string&h,int&status,uint64_t&length,bool&haslen){if(!validlinebytes(h))return false;auto e=h.find("\r\n");if(e==string::npos)return false;string_view line(h.data(),e);if(line.size()<12||(line.substr(0,9)!="HTTP/1.1 "&&line.substr(0,9)!="HTTP/1.0 ")||line[9]<'1'||line[9]>'9'||line[10]<'0'||line[10]>'9'||line[11]<'0'||line[11]>'9'||(line.size()>12&&line[12]!=' '))return false;status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';haslen=false;length=0;size_t p=e+2;while(p<h.size()){auto q=h.find("\r\n",p);if(q==string::npos)return false;if(q==p)break;string_view ln(h.data()+p,q-p);auto colon=ln.find(':');if(colon==string_view::npos||colon==0)return false;for(size_t i=0;i<colon;i++)if(!tokenchar((unsigned char)ln[i]))return false;for(size_t i=colon+1;i<ln.size();i++){unsigned char ch=ln[i];if((ch<32&&ch!='\t')||ch==127)return false;}string k=lower(string(ln.substr(0,colon)));if(k=="transfer-encoding")return false;if(k=="content-length"){if(haslen||!decimal(trim(ln.substr(colon+1)),length))return false;haslen=true;}p=q+2;}return true;}
void upfailure(Conn&c){if(c.state==Conn::AUTH)fail(c,503,false);else if(c.state==Conn::ORIGIN&&!c.upheaders)fail(c,502,false);else eraseconn(c.id);}
void upstream(Conn&c,uint32_t events){if(c.up<0)return;if(c.connecting&&(events&(EPOLLOUT|EPOLLERR|EPOLLHUP))){int err=0;socklen_t z=sizeof err;if(getsockopt(c.up,SOL_SOCKET,SO_ERROR,&err,&z)||err){upfailure(c);return;}c.connecting=false;}while(!c.connecting&&c.uspos<c.upsend.size()){ssize_t n=send(c.up,c.upsend.data()+c.uspos,c.upsend.size()-c.uspos,MSG_NOSIGNAL);if(n>0){c.uspos+=n;c.progress=Clock::now();continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;upfailure(c);return;}if(c.uspos<c.upsend.size()){update(c);return;}if(events&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR)){while(true){if(c.upheaders&&c.out.size()-c.opos>=131072)break;char buf[16384];ssize_t n=recv(c.up,buf,sizeof buf,0);if(n>0){c.progress=Clock::now();if(!c.upheaders){c.uphead.append(buf,n);auto end=c.uphead.find("\r\n\r\n");if(end==string::npos){if(c.uphead.size()>cfg.header||!validlinebytes(c.uphead)){upfailure(c);return;}continue;}if(end+4>cfg.header){upfailure(c);return;}int status;uint64_t len;bool haslen;if(!upstream_header(c.uphead.substr(0,end+4),status,len,haslen)){upfailure(c);return;}if(c.state==Conn::AUTH){closeup(c);if(status>=200&&status<300){if(!startup(c,false))fail(c,502,false);}else if(status==401||status==403)fail(c,status,false);else fail(c,503,false);return;}if(!haslen||status<200){upfailure(c);return;}c.upheaders=true;c.remaining=c.head?0:len;response(c,status,len);size_t have=c.uphead.size()-(end+4);size_t take=min<uint64_t>(have,c.remaining);if(take)c.out.append(c.uphead.data()+end+4,take);c.remaining-=take;c.uphead.clear();if(c.remaining==0){closeup(c);c.source_done=true;update(c);return;}}else{size_t take=min<uint64_t>(n,c.remaining);c.out.append(buf,take);c.remaining-=take;if(c.remaining==0){closeup(c);c.source_done=true;update(c);return;}}continue;}if(n==0){upfailure(c);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)break;upfailure(c);return;}}update(c);}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config"||!config(argv[2]))return 1;signal(SIGPIPE,SIG_IGN);rootfd=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(listener,(sockaddr*)&cfg.la,sizeof cfg.la)||listen(listener,1024))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;ctl(EPOLL_CTL_ADD,listener,0,EPOLLIN);epoll_event evs[512];auto sweep=Clock::now();while(true){int n=epoll_wait(ep,evs,512,25);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){uint64_t tag=evs[i].data.u64;if(tag==0){while(true){int fd=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(conns.size()>=cfg.maxconn){close(fd);continue;}uint64_t id=nextid++;auto c=make_unique<Conn>();c->id=id;c->fd=fd;c->last=c->progress=Clock::now();conns.emplace(id,move(c));ctl(EPOLL_CTL_ADD,fd,id<<1,EPOLLIN|EPOLLRDHUP);}continue;}uint64_t id=tag>>1;auto it=conns.find(id);if(it==conns.end())continue;Conn&c=*it->second;if(tag&1){upstream(c,evs[i].events);continue;}if(evs[i].events&EPOLLERR){eraseconn(id);continue;}if(c.state==Conn::READ&&(evs[i].events&(EPOLLIN|EPOLLRDHUP|EPOLLHUP))){readclient(c);if(!conns.count(id))continue;}auto it2=conns.find(id);if(it2==conns.end())continue;Conn&d=*it2->second;if(evs[i].events&EPOLLOUT)writeclient(d);else if((evs[i].events&EPOLLHUP)&&d.state!=Conn::READ)eraseconn(id);}auto now=Clock::now();if(now-sweep>=chrono::milliseconds(25)){sweep=now;vector<uint64_t> ids;ids.reserve(conns.size());for(auto &kv:conns)ids.push_back(kv.first);for(auto id:ids){auto it=conns.find(id);if(it==conns.end())continue;Conn&c=*it->second;if(c.state==Conn::READ){if(c.in.empty()){if(now-c.last>=chrono::milliseconds(cfg.idlems))eraseconn(id);}else if(now-c.first>=chrono::milliseconds(cfg.headms))fail(c,408,true);}else if(c.state==Conn::AUTH&&now-c.upstart>=chrono::milliseconds(cfg.authms))fail(c,503,false);else if((c.opos<c.out.size()||c.fileleft)&&now-c.progress>=chrono::milliseconds(cfg.writems))eraseconn(id);else if(c.state==Conn::ORIGIN&&c.up>=0&&now-c.progress>=chrono::milliseconds(cfg.idlems))upfailure(c);}}}return 0;}
